(2162560, 295170, 50205, '<td valign="top">I don''t know; I get the impression this is more about shock than creativity, but at least it''s different.</td>', 'I don''t know; I get the impression this is more about shock than creativity, but at least it''s different.', '2006-02-19 00:04:49.000000', NULL, 1),
(2162564, 295369, 50205, '<td valign="top">Should this really be in the competition?</td>', 'Should this really be in the competition?', '2006-02-19 00:07:09.000000', NULL, 1),
