(2162579, 295171, 50205, '<td valign="top">another glass picture.</td>', 'another glass picture.', '2006-02-19 00:14:40.000000', NULL, 1),
(2162581, 295902, 4210, '<td valign="top">I really like the reflection, but the yellowness of the skintone and the center-weighted subject detracts from it.</td>', 'I really like the reflection, but the yellowness of the skintone and the center-weighted subject detracts from it.', '2006-02-19 00:16:30.000000', NULL, 1),
(2162582, 295134, 50205, '<td valign="top">I like it</td>', 'I like it', '2006-02-19 00:16:53.000000', NULL, 1),
(2162586, 295740, 4210, '<td valign="top">Too center weighted, and the eye wanders from man to man to tree to tree without finding anything to really settle on.</td>', 'Too center weighted, and the eye wanders from man to man to tree to tree without finding anything to really settle on.', '2006-02-19 00:18:11.000000', NULL, 1),
(2162588, 293406, 50205, '<td valign="top">another picture of money</td>', 'another picture of money', '2006-02-19 00:18:45.000000', NULL, 1),
(2162590, 295806, 50205, '<td valign="top">ha, that''s pretty good</td>', 'ha, that''s pretty good', '2006-02-19 00:19:40.000000', NULL, 1),
(2162591, 294662, 4210, '<td valign="top">Quite pixelated. I think you mean for it to represent wrath, but without the title it''s difficult to make the connection.</td>', 'Quite pixelated. I think you mean for it to represent wrath, but without the title it''s difficult to make the connection.', '2006-02-19 00:19:43.000000', NULL, 1),
(2162592, 295170, 48471, '<td valign="top">9 A photo that really talks about sin and looks just as repelling as the sin should be. Good work.</td>', '9 A photo that really talks about sin and looks just as repelling as the sin should be. Good work.', '2006-02-19 00:19:53.000000', NULL, 1),
(2162593, 295391, 50205, '<td valign="top">It''s a good pic; I think your title hurts it.</td>', 'It''s a good pic; I think your title hurts it.', '2006-02-19 00:20:55.000000', NULL, 1),
(2162595, 293783, 4210, '<td valign="top">Cute. Good colours. Personally though, it just doesn''t do much for me.</td>', 'Cute. Good colours. Personally though, it just doesn''t do much for me.', '2006-02-19 00:21:30.000000', NULL, 1),
(2162598, 295810, 50205, '<td valign="top">shock or gluttony?  When I hear gluttony I don''t think of something like your picture.  It kind of screams for attention.</td>', 'shock or gluttony?  When I hear gluttony I don''t think of something like your picture.  It kind of screams for attention.', '2006-02-19 00:22:20.000000', NULL, 1),
(2162600, 295793, 4210, '<td valign="top">Nice macro. Good composition.</td>', 'Nice macro. Good composition.', '2006-02-19 00:22:28.000000', NULL, 1),
(2162604, 295289, 4210, '<td valign="top">Cute, but you can tell it''s staged by the background and lighting.</td>', 'Cute, but you can tell it''s staged by the background and lighting.', '2006-02-19 00:23:20.000000', NULL, 1),
(2162608, 294545, 4210, '<td valign="top">A great capture. I wish I could see the whole tail though. Love those teeth!</td>', 'A great capture. I wish I could see the whole tail though. Love those teeth!', '2006-02-19 00:24:02.000000', NULL, 1),
(2162609, 295850, 4210, '<td valign="top">Unclear, and I can''t really tell what it is.</td>', 'Unclear, and I can''t really tell what it is.', '2006-02-19 00:25:36.000000', NULL, 1),
(2162610, 295636, 48471, '<td valign="top">3 I don''t understand it - what does this has to do with any of the sins? Why you have such harsh transition from overexposed flower to a very dark background, whatever that is? Why the photo is not in focus?</td>', '3 I don''t understand it - what does this has to do with any of the sins? Why you have such harsh transition from overexposed flower to a very dark background, whatever that is? Why the photo is not in focus?', '2006-02-19 00:25:40.000000', NULL, 1),
(2162613, 295029, 50205, '<td valign="top">very good</td>', 'very good', '2006-02-19 00:25:54.000000', NULL, 1),
(2162614, 295767, 50205, '<td valign="top">good idea</td>', 'good idea', '2006-02-19 00:26:11.000000', NULL, 1),
(2162615, 295289, 32608, '<td valign="top">sad to see the background, still cute.  6</td>', 'sad to see the background, still cute.  6', '2006-02-19 00:26:24.000000', NULL, 1),
(2162619, 293416, 50205, '<td valign="top">I don''t like the border; the picture is fine without it.</td>', 'I don''t like the border; the picture is fine without it.', '2006-02-19 00:26:56.000000', NULL, 1),
(2162622, 292961, 50205, '<td valign="top">way way too many of these</td>', 'way way too many of these', '2006-02-19 00:27:30.000000', NULL, 1),
(2162624, 293357, 50205, '<td valign="top">nice pick, but sloth?  Also, I think it''s fine without a border.</td>', 'nice pick, but sloth?  Also, I think it''s fine without a border.', '2006-02-19 00:28:00.000000', NULL, 1),
(2162626, 294398, 50205, '<td valign="top">hmm, it''s interesting.</td>', 'hmm, it''s interesting.', '2006-02-19 00:28:41.000000', NULL, 1),
(2162629, 295735, 48471, '<td valign="top">3 I guess many people will complain about the photo not being in focus. I''ll complain about the story: I don''t see it being about any of the sins, just a happy snapshot to have fun with later. I don''t see this being interesting outside the family circle.</td>', '3 I guess many people will complain about the photo not being in focus. I''ll complain about the story: I don''t see it being about any of the sins, just a happy snapshot to have fun with later. I don''t see this being interesting outside the family circle.', '2006-02-19 00:29:28.000000', NULL, 1),
(2162630, 295318, 50205, '<td valign="top">I don''t like the picture, but at least you''re trying to be creative. 7</td>', 'I don''t like the picture, but at least you''re trying to be creative. 7', '2006-02-19 00:29:34.000000', NULL, 1),
(2162636, 295589, 4210, '<td valign="top">She doesn''t look very envious. It looks more like a generic snapshot.</td>', 'She doesn''t look very envious. It looks more like a generic snapshot.', '2006-02-19 00:36:07.000000', NULL, 1),
(2162637, 295763, 4210, '<td valign="top">Clever. Well done and well lit.</td>', 'Clever. Well done and well lit.', '2006-02-19 00:36:58.000000', NULL, 1),
(2162639, 295679, 22734, '<td valign="top">Cool! Bumping up.</td>', 'Cool! Bumping up.', '2006-02-19 00:38:24.000000', NULL, 1),
(2162644, 295023, 22734, '<td valign="top">Indeed sensual. There is a naturalness that trasnmits the humor and message. Nice pleasing color tones and sharp facial expressions. Bumping up.</td>', 'Indeed sensual. There is a naturalness that trasnmits the humor and message. Nice pleasing color tones and sharp facial expressions. Bumping up.', '2006-02-19 00:42:05.000000', NULL, 1),
(2162648, 294398, 4210, '<td valign="top">This would be a much stronger photo without the person in the background. Honestly, the shoe is awesome, and it would look great on a plain white background.</td>', 'This would be a much stronger photo without the person in the background. Honestly, the shoe is awesome, and it would look great on a plain white background.', '2006-02-19 00:43:46.000000', NULL, 1),
(2162650, 295349, 4210, '<td valign="top">Interesting. Very artistic.</td>', 'Interesting. Very artistic.', '2006-02-19 00:44:27.000000', NULL, 1),
(2162652, 295675, 22734, '<td valign="top">lol. A very strong image with a shade of bloody humor. Bumping up for its horror projection.</td>', 'lol. A very strong image with a shade of bloody humor. Bumping up for its horror projection.', '2006-02-19 00:45:18.000000', NULL, 1),
(2162653, 295279, 4210, '<td valign="top">Not sure what this has to do with deadly sins...?</td>', 'Not sure what this has to do with deadly sins...?', '2006-02-19 00:45:31.000000', NULL, 1),
(2162657, 295373, 4210, '<td valign="top">Blurry, out of focus, and they''re pennies (not exactly representing greed)</td>', 'Blurry, out of focus, and they''re pennies (not exactly representing greed)', '2006-02-19 00:46:21.000000', NULL, 1),
(2162661, 295565, 22734, '<td valign="top">One of those highly explosive and impressive visuals with a slight suggestion of the surreal. Bumping up.</td>', 'One of those highly explosive and impressive visuals with a slight suggestion of the surreal. Bumping up.', '2006-02-19 00:47:06.000000', NULL, 1),
(2162664, 295507, 4210, '<td valign="top">If he''s eating, why is he stuffing food into his cheek??<br/>But I really like the black and white on this image.</td>', 'If he''s eating, why is he stuffing food into his cheek??But I really like the black and white on this image.', '2006-02-19 00:48:03.000000', NULL, 1),
(2162666, 293453, 22734, '<td valign="top">Crisp detail and great use of these wonderful models. Bumping up.</td>', 'Crisp detail and great use of these wonderful models. Bumping up.', '2006-02-19 00:48:38.000000', NULL, 1),
(2162667, 295810, 4210, '<td valign="top">Wow, this image is really scary. Wow. Excellent.</td>', 'Wow, this image is really scary. Wow. Excellent.', '2006-02-19 00:49:09.000000', NULL, 1),
(2162669, 295806, 22734, '<td valign="top">lol. What a beautiful find for this challenge. Bumping up.</td>', 'lol. What a beautiful find for this challenge. Bumping up.', '2006-02-19 00:49:50.000000', NULL, 1),
(2162670, 295765, 4210, '<td valign="top">A strong visual.</td>', 'A strong visual.', '2006-02-19 00:49:52.000000', NULL, 1),
(2162673, 295074, 22734, '<td valign="top">Very good tonal strebgth to accent the growl. Bumping up.</td>', 'Very good tonal strebgth to accent the growl. Bumping up.', '2006-02-19 00:50:23.000000', NULL, 1),
(2162674, 293406, 4210, '<td valign="top">Seems out of focus, but I like the colour.</td>', 'Seems out of focus, but I like the colour.', '2006-02-19 00:50:27.000000', NULL, 1),
(2162678, 295134, 22734, '<td valign="top">A very nice study and one I would have loved to see in a high contrast b/w. Nevertheless, the image works very well as is. Bumping up.</td>', 'A very nice study and one I would have loved to see in a high contrast b/w. Nevertheless, the image works very well as is. Bumping up.', '2006-02-19 00:51:51.000000', NULL, 1),
(2162679, 295914, 4210, '<td valign="top">I wonder why lust is missing, and why, if that is significant, that it is not manifest in the image in other ways...</td>', 'I wonder why lust is missing, and why, if that is significant, that it is not manifest in the image in other ways...', '2006-02-19 00:52:14.000000', NULL, 1),
(2162681, 295750, 22734, '<td valign="top">Very nice b/w capture with convincing facial expression. Bumping up.</td>', 'Very nice b/w capture with convincing facial expression. Bumping up.', '2006-02-19 00:52:50.000000', NULL, 1),
(2162682, 295767, 4210, '<td valign="top">An interesting idea to present this image in black and white</td>', 'An interesting idea to present this image in black and white', '2006-02-19 00:53:06.000000', NULL, 1),
(2162687, 295902, 22734, '<td valign="top">Nicely done! Bumping up.</td>', 'Nicely done! Bumping up.', '2006-02-19 00:53:48.000000', NULL, 1),
(2162688, 295838, 4210, '<td valign="top">I wish the bottom of the boot wasn''t cropped like that, but otherwise and extremely strong image.</td>', 'I wish the bottom of the boot wasn''t cropped like that, but otherwise and extremely strong image.', '2006-02-19 00:53:59.000000', NULL, 1),
(2162691, 293064, 4210, '<td valign="top">So, wait.... why the doll?</td>', 'So, wait.... why the doll?', '2006-02-19 00:54:41.000000', NULL, 1),
(2162693, 294693, 4210, '<td valign="top">The lighting on the bike isn''t enough to really give it the "pop" this image deserves.</td>', 'The lighting on the bike isn''t enough to really give it the "pop" this image deserves.', '2006-02-19 00:56:00.000000', NULL, 1);
