(2162695, 293586, 4210, '<td valign="top">This looks like it was ALOT of fun to shoot.</td>', 'This looks like it was ALOT of fun to shoot.', '2006-02-19 00:58:22.000000', NULL, 1),
(2162696, 295722, 22734, '<td valign="top">Very well put together with multiple ingredients working well with one another to produce a dynamic and sensual image. The hand and finger positions are great, the bite on the strawberry and good angle, then the expressive eye but above all the way the hair that sweeps like a mane to adorn the whole and what a good choice to have avoided the earrings! Lovely. Bumping up. 7</td>', 'Very well put together with multiple ingredients working well with one another to produce a dynamic and sensual image. The hand and finger positions are great, the bite on the strawberry and good angle, then the expressive eye but above all the way the hair that sweeps like a mane to adorn the whole and what a good choice to have avoided the earrings! Lovely. Bumping up. 7', '2006-02-19 00:58:54.000000', NULL, 1),
(2162698, 295171, 4210, '<td valign="top">A very strong image, but I''m not sure how it relates to greed exactly...</td>', 'A very strong image, but I''m not sure how it relates to greed exactly...', '2006-02-19 01:00:17.000000', NULL, 1),
(2162699, 294595, 22734, '<td valign="top">This guy, while not captured with the clarity needed for competition, is one of the sweetest animal capture. Why, just the head resting on the icy pillow and then his leggs crossed are enough to melt any heart. Great sloth presenrarion. Bumping up.</td>', 'This guy, while not captured with the clarity needed for competition, is one of the sweetest animal capture. Why, just the head resting on the icy pillow and then his leggs crossed are enough to melt any heart. Great sloth presenrarion. Bumping up.', '2006-02-19 01:01:29.000000', NULL, 1),
