(2167347, 294706, 44611, '<td valign="top">Junk food may be sinful, but I don''t really think this image displays them as such.</td>', 'Junk food may be sinful, but I don''t really think this image displays them as such.', '2006-02-21 06:41:52.000000', NULL, 1),
(2167349, 293644, 44611, '<td valign="top">Good concept but rather an unclear image sadly.  Too much of the door and not enough of the light shining through the lingerie on the doorknob.</td>', 'Good concept but rather an unclear image sadly.  Too much of the door and not enough of the light shining through the lingerie on the doorknob.', '2006-02-21 06:42:52.000000', NULL, 1),
(2167350, 295850, 44611, '<td valign="top">I am unclear what is being shown here.</td>', 'I am unclear what is being shown here.', '2006-02-21 06:43:46.000000', NULL, 1),
(2167351, 295798, 44611, '<td valign="top">Composition is off - too centred and part of the camera cut out of the picture.  Try to use the rule of thirds in your composition and don''t cut off crucial elements of your subject.</td>', 'Composition is off - too centred and part of the camera cut out of the picture.  Try to use the rule of thirds in your composition and don''t cut off crucial elements of your subject.', '2006-02-21 06:45:33.000000', NULL, 1),
(2167353, 295373, 44611, '<td valign="top">Good concept but the slight motion blur of the hands doesn''t really add to this image.  Would have been better, imho, if the focus on the hands had been sharp.</td>', 'Good concept but the slight motion blur of the hands doesn''t really add to this image.  Would have been better, imho, if the focus on the hands had been sharp.', '2006-02-21 06:46:37.000000', NULL, 1),
(2167354, 294460, 44611, '<td valign="top">Ok, I''m probably not getting this but what is the connection with sins?  It''s too obscure a jump for my little brain!</td>', 'Ok, I''m probably not getting this but what is the connection with sins?  It''s too obscure a jump for my little brain!', '2006-02-21 06:47:41.000000', NULL, 1),
(2167355, 295170, 44611, '<td valign="top">This comes out quite dark on my monitor and I guess you may get a few comments to that effect.  It makes the distinctions in contrast, particularly in b &amp; w, difficult and the focus look rather soft.</td>', 'This comes out quite dark on my monitor and I guess you may get a few comments to that effect.  It makes the distinctions in contrast, particularly in b & w, difficult and the focus look rather soft.', '2006-02-21 06:49:36.000000', NULL, 1),
