(2169744, 293849, 41802, '<td valign="top">Personally I gave you a 6.  I like the shot, the sky is amazing.</td>', 'Personally I gave you a 6.  I like the shot, the sky is amazing.', '2006-02-22 01:08:02.000000', NULL, 0),
(2169748, 293453, 20662, '<td valign="top">No snails were harmed... I love it!<br/> <br/>Congratulations Phillip. You disappeared for so long that I thought maybe you''d given up on photography. When you come back you come back strong! Way to go.</td>', 'No snails were harmed... I love it! Congratulations Phillip. You disappeared for so long that I thought maybe you''d given up on photography. When you come back you come back strong! Way to go.', '2006-02-22 01:10:25.000000', NULL, 0),
